using Microsoft.Web.WebView2.Core;
using System.Text.Json;
namespace AetherOnePC;
public sealed partial class BrowserForm
{
    private BrowserTab? lastSelected;
    private bool TrimHidden(BrowserTab p){if(p.Web==null||p==Current)return false;_=SuspendHiddenAsync(p);return true;}
    private static void RestoreMemoryTarget(BrowserTab? p){p?.CancelMemory?.Cancel();if(p?.Web is not {IsDisposed:false} w)return;try{if(w.CoreWebView2!=null){if(p.SuspendUnavailable)w.CoreWebView2.MemoryUsageTargetLevel=CoreWebView2MemoryUsageTargetLevel.Normal;else w.CoreWebView2.Resume();p.Suspended=false;}}catch{}}
    private Task? extensionCatalog;
    private readonly Dictionary<string,CoreWebView2BrowserExtension> loadedExtensions=[];
    private string extensionMessage="";
    private bool installingExtension;
    private Task<CoreWebView2Environment> CreateEnvironment()=>CoreWebView2Environment.CreateAsync(null,Path.Combine(profilePath,"WebView"),new CoreWebView2EnvironmentOptions{AreBrowserExtensionsEnabled=true});
    private bool IsAllowedExtensionPage(BrowserTab tab,string value)=>Uri.TryCreate(value,UriKind.Absolute,out var u)&&u.Scheme=="chrome-extension"&&u.Host==tab.ExtensionOrigin&&loadedExtensions.TryGetValue(u.Host,out var e)&&e.IsEnabled;
    private async Task LoadExtensionCatalog(CoreWebView2 core){if(extensionCatalog!=null){await extensionCatalog;return;}extensionCatalog=LoadCatalog(core);await extensionCatalog;}
    private async Task LoadCatalog(CoreWebView2 core){state.ExtensionFolders??=[];state.PinnedExtensions??=[];foreach(var e in await core.Profile.GetBrowserExtensionsAsync()){if(e.Name=="Aether Reading Tools"&&!state.RemovedReadingTools){await e.RemoveAsync();state.ExtensionFolders.Remove(e.Id);state.PinnedExtensions.Remove(e.Id);}else loadedExtensions[e.Id]=e;}state.RemovedReadingTools=true;QueueSave();RefreshExtensionPins();}
    private static string ManifestSummary(string folder){using var doc=JsonDocument.Parse(File.ReadAllText(Path.Combine(folder,"manifest.json")));var j=doc.RootElement;string name=j.TryGetProperty("name",out var n)?n.GetString()??"Extension":"Extension";var details=new List<string>();foreach(var k in new[]{"permissions","host_permissions","content_scripts"})if(j.TryGetProperty(k,out var p))details.Add(k+": "+p.GetRawText());return name+"\n\n"+string.Join("\n",details);}
    private async Task<CoreWebView2BrowserExtension?> ImportExtension(CoreWebView2 core,string source,bool confirm=true)
    {
        var info=new FileInfo(Path.Combine(source,"manifest.json"));if(!info.Exists||info.Length>1024*1024)throw new InvalidDataException("Choose a folder containing manifest.json (up to 1 MiB).");string summary=ManifestSummary(source);if(confirm&&MessageBox.Show(this,summary+"\n\nAllow this extension the declared access? Load only extensions you trust.","Add extension",MessageBoxButtons.OKCancel,MessageBoxIcon.Question)!=DialogResult.OK)return null;
        string target=Path.Combine(profilePath,"Extensions","Imported-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(target);int count=0;long bytes=0;
        void Copy(string src,string dst,int depth){if(depth>24||(new DirectoryInfo(src).Attributes&FileAttributes.ReparsePoint)!=0)throw new InvalidDataException("Junctions, links and deeply nested folders are not imported.");foreach(var item in new DirectoryInfo(src).EnumerateFileSystemInfos()){if((item.Attributes&FileAttributes.ReparsePoint)!=0)throw new InvalidDataException("Extension contains a link");if(item.Name=="_metadata")continue;if(++count>20000)throw new InvalidDataException("Too many extension files");string path=Path.Combine(dst,item.Name);if(item is DirectoryInfo){Directory.CreateDirectory(path);Copy(item.FullName,path,depth+1);}else{bytes+=((FileInfo)item).Length;if(bytes>CrxPackage.MaxUnpackedBytes)throw new InvalidDataException("Extension exceeds the 512 MiB unpacked limit");File.Copy(item.FullName,path);}}}
        try{await Task.Run(()=>Copy(source,target,0));var e=await core.Profile.AddBrowserExtensionAsync(target);loadedExtensions[e.Id]=e;state.ExtensionFolders[e.Id]=target;QueueSave();RefreshExtensionPins();return e;}catch{try{Directory.Delete(target,true);}catch{}throw;}
    }
    private async Task LoadUnpacked(BrowserTab p){using var folder=new FolderBrowserDialog{Description="Select the folder containing manifest.json",UseDescriptionForTitle=true};if(folder.ShowDialog(this)!=DialogResult.OK)return;try{await Ensure(p);await ImportExtension(p.Web!.CoreWebView2,folder.SelectedPath);extensionMessage="Extension added. Reload open websites to activate its content scripts.";}catch(Exception e){extensionMessage=e.Message;MessageBox.Show(this,e.Message,"Extension could not be loaded");}OpenInternal("extensions",p);}
    private async Task LoadCrx(BrowserTab p){using var file=new OpenFileDialog{Filter="Chrome extension (*.crx)|*.crx"};if(file.ShowDialog(this)!=DialogResult.OK)return;await InstallCrxBytes(await File.ReadAllBytesAsync(file.FileName),null,p,true);}
    private async Task ChangeExtension(CoreWebView2BrowserExtension e,BrowserTab p){try{await e.EnableAsync(!e.IsEnabled);extensionPinKey="";RefreshExtensionPins();OpenInternal("extensions",p);}catch(Exception x){MessageBox.Show(this,x.Message,"Extension action failed");}}
    private async Task RemoveExtension(CoreWebView2BrowserExtension e,BrowserTab p){if(MessageBox.Show(this,"Remove "+e.Name+" and its extension data?","Remove extension",MessageBoxButtons.OKCancel)!=DialogResult.OK)return;try{await e.RemoveAsync();loadedExtensions.Remove(e.Id);state.ExtensionFolders.Remove(e.Id);state.PinnedExtensions.Remove(e.Id);QueueSave();RefreshExtensionPins();OpenInternal("extensions",p);}catch(Exception x){MessageBox.Show(this,x.Message,"Extension action failed");}}
    private async Task InstallStore(string url)
    {
        string? id=CrxPackage.StoreId(url);if(id==null){MessageBox.Show(this,"Paste the extension's chromewebstore.google.com/detail listing URL.","Chrome Web Store");return;}if(installingExtension)return;installingExtension=true;var p=Current!;extensionMessage="Downloading signed extension…";
        try{if(storeButton!=null){storeButton.Text="Downloading extension…";storeButton.Enabled=false;}await Ensure(p);string version=p.Web!.CoreWebView2.Environment.BrowserVersionString.Split(' ')[0];byte[] bytes=await DownloadStorePackage(id,version);await InstallCrxBytes(bytes,id,p,true);}catch(Exception e){extensionMessage="Installation failed: "+e.Message;MessageBox.Show(this,extensionMessage,"Chrome Web Store installation");}finally{installingExtension=false;if(storeButton!=null){storeButton.Enabled=true;storeButton.Text="Install extension";}}
    }
    private static async Task<byte[]> DownloadStorePackage(string id,string version)
    {
        if(!CrxPackage.ValidId(id))throw new InvalidDataException("Invalid store ID");string url="https://clients2.google.com/service/update2/crx?response=redirect&acceptformat=crx3&prodversion="+Uri.EscapeDataString(version)+"&x="+Uri.EscapeDataString("id="+id+"&installsource=ondemand&uc");using var cts=new CancellationTokenSource(TimeSpan.FromSeconds(90));using var response=await network.GetAsync(url,HttpCompletionOption.ResponseHeadersRead,cts.Token);response.EnsureSuccessStatusCode();if(response.RequestMessage?.RequestUri?.Scheme!="https")throw new InvalidDataException("Extension download did not use HTTPS");if(response.Content.Headers.ContentLength>100*1024*1024)throw new InvalidDataException("Extension package exceeds 100 MiB");using var input=await response.Content.ReadAsStreamAsync(cts.Token);using var output=new MemoryStream();var buffer=new byte[32768];int n;while((n=await input.ReadAsync(buffer,cts.Token))>0){if(output.Length+n>100*1024*1024)throw new InvalidDataException("Extension download too large");output.Write(buffer,0,n);}return output.ToArray();
    }
    private async Task InstallCrxBytes(byte[] bytes,string? id,BrowserTab p,bool confirm)
    {
        string stage=Path.Combine(profilePath,"ExtensionStaging",Guid.NewGuid().ToString("N"));try{var package=await Task.Run(()=>CrxPackage.Verify(bytes,id));await Task.Run(()=>CrxPackage.Extract(package,stage));await Ensure(p);var e=await ImportExtension(p.Web!.CoreWebView2,stage,confirm);if(e==null){extensionMessage="Installation cancelled.";return;}if(e.Id!=package.Id){await e.RemoveAsync();loadedExtensions.Remove(e.Id);state.ExtensionFolders.Remove(e.Id);throw new InvalidDataException("Engine extension identity mismatch");}extensionMessage="Added "+e.Name+". Reload open websites to activate it.";OpenInternal("extensions",p);}catch(Exception e){extensionMessage=e.Message;if(smoke)throw;MessageBox.Show(this,e.Message,"Extension installation failed");}finally{try{if(Directory.Exists(stage))Directory.Delete(stage,true);}catch{}}
    }
    private Task ExtensionsDialog(string? capturePath=null){OpenInternal("extensions");return Task.CompletedTask;}
    private async Task OpenExtensionPage(CoreWebView2BrowserExtension e)
    {
        try{if(!e.IsEnabled||!state.ExtensionFolders.TryGetValue(e.Id,out var folder))return;using var doc=JsonDocument.Parse(File.ReadAllText(Path.Combine(folder,"manifest.json")));var j=doc.RootElement;string? entry=null;if(j.TryGetProperty("options_page",out var op))entry=op.GetString();else if(j.TryGetProperty("options_ui",out var ui)&&ui.TryGetProperty("page",out var page))entry=page.GetString();else if(j.TryGetProperty("action",out var action)&&action.TryGetProperty("default_popup",out var pop))entry=pop.GetString();if(string.IsNullOrEmpty(entry)){MessageBox.Show(this,"This extension has no options or popup page. Its content scripts may still run on supported websites.",e.Name);return;}
            string full=Path.GetFullPath(Path.Combine(folder,entry.Replace('/',Path.DirectorySeparatorChar)));if(!full.StartsWith(Path.GetFullPath(folder)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)||!File.Exists(full))throw new InvalidDataException("Invalid extension entry page");NewTab();var p=Current!;await Ensure(p);p.ExtensionOrigin=e.Id;p.AtHome=false;p.Home.Visible=false;p.Web!.Visible=true;p.Web.BringToFront();p.Web.CoreWebView2.Navigate("chrome-extension://"+e.Id+"/"+entry.TrimStart('/'));}catch(Exception ex){MessageBox.Show(this,ex.Message,"Extension options");}
    }
}
